from collections import deque

def trans(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    dirs4=[(1,0),(-1,0),(0,1),(0,-1)]
    dirs8=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)]
    # all zero components and whether exterior
    zseen=set(); holes=[]; exterior=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]==0 and (r,c) not in zseen:
        q=[(r,c)]; zseen.add((r,c)); comp=[]; edge=False
        for y,x in q:
         comp.append((y,x))
         if y==0 or x==0 or y==h-1 or x==w-1: edge=True
         for dy,dx in dirs4:
          yy,xx=y+dy,x+dx
          if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in zseen:
           zseen.add((yy,xx)); q.append((yy,xx))
        (exterior if edge else holes).update(comp)
    # eligible 1 comps 4-connected neighboring hole region, maybe through 8
    seen=set(); eligible=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]==1 and (r,c) not in seen:
        q=[(r,c)]; seen.add((r,c)); comp=[]
        for y,x in q:
         comp.append((y,x))
         for dy,dx in dirs4:
          yy,xx=y+dy,x+dx
          if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen:
           seen.add((yy,xx)); q.append((yy,xx))
        # touches enclosed zero through 8 adjacency
        hit=any((y+dy,x+dx) in holes for y,x in comp for dy,dx in dirs8 if 0<=y+dy<h and 0<=x+dx<w)
        if hit: eligible.update(comp)
    # fill cavity boundary cells in holes with 3
    for r,c in holes:
      if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1 for dr,dc in dirs8): out[r][c]=3
    # outside 8-neighbor shell of eligible component -> 2
    for r,c in eligible:
      for dr,dc in dirs8:
       y,x=r+dr,c+dc
       if 0<=y<h and 0<=x<w and grid[y][x]==0 and (y,x) in exterior: out[y][x]=2
    return out
